import heapq

def bfs(vis, l, u, xi, yi):
    q = []
    heapq.heappush(q, (0, l, u))
    vis[l][u] = 1
    f = [(0,1), (1,0), (0,-1), (-1,0)]
    while q:
        step, ex, ey = heapq.heappop(q)
        if ex == xi and ey == yi:
            return step
        for dx, dy in f:
            tx = ex + dx
            ty = ey + dy
            tstep = step + 1
            if tx < 0 or ty < 0:
                continue
            if tx >= 110 or ty >= 110:
                continue
            if vis[tx][ty]:
                continue
            vis[tx][ty] = 1
            heapq.heappush(q, (tstep, tx, ty))
    return None

def main():
    s = input().strip()
    length = len(s)
    x = 0
    y = 0
    xx = 0
    yy = 0
    for i in range(length):
        if s[i] == 'L':
            y -= 1
        if s[i] == 'R':
            y += 1
        if s[i] == 'U':
            x -= 1
        if s[i] == 'D':
            x += 1
        xx = min(xx, x)
        yy = min(yy, y)
    xx = -xx
    yy = -yy

    vis = [[1]*110 for _ in range(110)]

    x = xx
    y = yy
    for i in range(length):
        if s[i] == 'L':
            y -= 1
        if s[i] == 'R':
            y += 1
        if s[i] == 'U':
            x -= 1
        if s[i] == 'D':
            x += 1
        vis[x][y] = 0

    ans = bfs(vis, xx, yy, x, y)

    if ans == length:
        print("OK")
    else:
        print("BUG")

if __name__ == "__main__":
    main()
```

